#!/usr/bin/env python3
"""Compute machine-readable reference data for CSX-126_Q1."""

from __future__ import annotations

import json
from collections import defaultdict
from datetime import datetime
from pathlib import Path
from typing import Any


TASK_ID = "CSX-126_Q1"
PACKAGE_ID = "CSX-126"
ANSWER = "compound_oman_landfall_rain_gust_pressure_window"
TARGET_FAMILY = "gonu_oman_landfall_rain_gust_pressure_window_consistency_proof"

SOURCE_FILES = [
    "metadata/event.json",
    "data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json",
    "data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json",
    "data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_006_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json",
    "data/exposure_impact/exposure_impact_005_OpenStreetMap_Overpass_bounded_AOI_slice.json",
    "data/remote_sensing/remote_sensing_004_Sentinel-1_GRD_VV_pre_post_change.json",
]

OSM_CONTEXT_PATTERN = "data/exposure_impact/exposure_impact_005_OpenStreetMap_Overpass_bounded_*_slice.json"


def repo_root() -> Path:
    here = Path(__file__).resolve()
    for candidate in [here.parent, *here.parents]:
        if (candidate / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID).is_dir():
            return candidate
    raise RuntimeError("Could not locate repository root from compute_gt.py")


def load_json(package_dir: Path, rel_path: str) -> Any:
    return json.loads((package_dir / rel_path).read_text(encoding="utf-8-sig"))


def load_json_match(package_dir: Path, pattern: str) -> Any:
    matches = sorted(package_dir.glob(pattern))
    if not matches:
        raise FileNotFoundError(f"No package file matched {pattern}")
    return json.loads(matches[0].read_text(encoding="utf-8-sig"))


def finite(values: list[Any]) -> list[float]:
    return [float(value) for value in values if value is not None]


def extreme_with_time(times: list[str], values: list[Any], mode: str) -> dict[str, Any]:
    numeric = [(idx, float(value)) for idx, value in enumerate(values) if value is not None]
    if not numeric:
        raise ValueError("No numeric values available for extreme calculation")
    idx, value = min(numeric, key=lambda item: item[1]) if mode == "min" else max(numeric, key=lambda item: item[1])
    return {"time": times[idx], "value": round(value, 3)}


def parse_time(value: str) -> datetime:
    return datetime.strptime(value, "%Y-%m-%dT%H:%M")


def summarize_osm(osm_data: dict[str, Any]) -> dict[str, Any]:
    amenities: dict[str, int] = {}
    for element in osm_data.get("elements", []):
        amenity = (element.get("tags") or {}).get("amenity")
        if amenity:
            amenities[amenity] = amenities.get(amenity, 0) + 1
    return {
        "element_count": len(osm_data.get("elements", [])),
        "top_amenities": dict(sorted(amenities.items(), key=lambda item: (-item[1], item[0]))[:5]),
    }


def main() -> None:
    package_dir = repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID
    event = load_json(package_dir, "metadata/event.json")

    open_meteo = load_json(
        package_dir,
        "data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json",
    )
    hourly = open_meteo["hourly"]
    times = hourly["time"]
    daily_precip: defaultdict[str, float] = defaultdict(float)
    for time_value, precip in zip(times, hourly["precipitation"]):
        if precip is not None:
            daily_precip[time_value[:10]] += float(precip)

    precip_total = round(sum(finite(hourly["precipitation"])), 3)
    peak_hour = extreme_with_time(times, hourly["precipitation"], "max")
    peak_day_date, peak_day_value_raw = max(daily_precip.items(), key=lambda item: item[1])
    peak_day_value = round(peak_day_value_raw, 3)
    peak_day_fraction = round(peak_day_value / precip_total, 3)
    peak_hour_fraction = round(peak_hour["value"] / precip_total, 3)

    max_wind = extreme_with_time(times, hourly["wind_speed_10m"], "max")
    max_gust = extreme_with_time(times, hourly["wind_gusts_10m"], "max")
    min_pressure = extreme_with_time(times, hourly["pressure_msl"], "min")
    cotiming_times = [parse_time(max_gust["time"]), parse_time(max_wind["time"]), parse_time(min_pressure["time"])]
    cotiming_span_hours_inclusive = int((max(cotiming_times) - min(cotiming_times)).total_seconds() // 3600) + 1
    gust_to_wind_ratio = round(max_gust["value"] / max_wind["value"], 3)

    power = load_json(
        package_dir,
        "data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json",
    )
    power_params = power["properties"]["parameter"]
    power_precip = {date: float(value) for date, value in power_params["PRECTOTCORR"].items()}
    power_wind = {date: float(value) for date, value in power_params["WS10M"].items()}
    nasa_precip_total = round(sum(power_precip.values()), 3)
    nasa_peak_precip_date = max(power_precip, key=power_precip.get)
    nasa_peak_wind_date = max(power_wind, key=power_wind.get)
    nasa_same_day = nasa_peak_precip_date == nasa_peak_wind_date == peak_day_date.replace("-", "")
    open_to_nasa_total_ratio = round(precip_total / nasa_precip_total, 3)

    era5 = load_json(package_dir, "data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json")
    gpm = load_json(package_dir, "data/physical_hazard/physical_hazard_006_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = load_json(package_dir, "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json")
    regional_maxima = {
        "era5_mm": round(era5["stats"]["precipitation_sum_mm_max"], 3),
        "gpm_mm": round(gpm["stats"]["gpm_event_precip_mm_max"], 3),
        "chirps_mm": round(chirps["stats"]["chirps_event_precip_mm_max"], 3),
    }
    regional_ratios = {
        "open_meteo_to_era5": round(precip_total / regional_maxima["era5_mm"], 3),
        "open_meteo_to_gpm": round(precip_total / regional_maxima["gpm_mm"], 3),
        "open_meteo_to_chirps": round(precip_total / regional_maxima["chirps_mm"], 3),
    }

    worldpop = load_json(package_dir, "data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json")
    osm_data = load_json_match(package_dir, OSM_CONTEXT_PATTERN)
    osm_summary = summarize_osm(osm_data)
    sentinel = load_json(package_dir, "data/remote_sensing/remote_sensing_004_Sentinel-1_GRD_VV_pre_post_change.json")

    rows = [
        {
            "row_id": "landfall_peak_day_concentration",
            "formula": "peak_daily_precipitation_mm / event_total_mm; peak_hourly_precipitation_mm / event_total_mm",
            "expected_values": {
                "event_total_mm": precip_total,
                "peak_day": peak_day_date,
                "peak_day_mm": peak_day_value,
                "peak_day_fraction": peak_day_fraction,
                "peak_hour_time": peak_hour["time"],
                "peak_hour_mm": peak_hour["value"],
                "peak_hour_fraction": peak_hour_fraction,
            },
            "decision": "passes_landfall_day_concentration_not_single_hour_replacement",
        },
        {
            "row_id": "wind_pressure_timing_window",
            "formula": "inclusive hour span from max gust to max wind and minimum pressure; max_gust_kmh / max_wind_kmh",
            "expected_values": {
                "max_gust_kmh": max_gust["value"],
                "max_gust_time": max_gust["time"],
                "max_wind_kmh": max_wind["value"],
                "max_wind_time": max_wind["time"],
                "min_pressure_hpa": min_pressure["value"],
                "min_pressure_time": min_pressure["time"],
                "co_timing_span_hours_inclusive": cotiming_span_hours_inclusive,
                "gust_to_wind_ratio": gust_to_wind_ratio,
            },
            "decision": "passes_tight_landfall_day_wind_pressure_window",
        },
        {
            "row_id": "independent_daily_same_day_support",
            "formula": "NASA peak precip date equals NASA peak wind date equals Open-Meteo peak rain date; Open-Meteo total / NASA total",
            "expected_values": {
                "nasa_precip_total_mm": nasa_precip_total,
                "nasa_peak_precip_date": nasa_peak_precip_date,
                "nasa_peak_precip_mm": round(power_precip[nasa_peak_precip_date], 3),
                "nasa_peak_wind_date": nasa_peak_wind_date,
                "nasa_peak_wind_mps": round(power_wind[nasa_peak_wind_date], 3),
                "same_day_support": nasa_same_day,
                "open_meteo_to_nasa_total_ratio": open_to_nasa_total_ratio,
            },
            "decision": "supports_landfall_day_timing_with_lower_daily_magnitude",
        },
        {
            "row_id": "regional_precip_max_context",
            "formula": "Open-Meteo event total divided by each regional precipitation maximum",
            "expected_values": {
                "regional_maxima_mm": regional_maxima,
                "point_to_regional_ratios": regional_ratios,
            },
            "decision": "regional_maxima_are_context_not_replacement_for_point_timing_proof",
        },
        {
            "row_id": "map_layer_nonreplacement_check",
            "formula": "derived exposure/map summaries and Sentinel pre/post scene counts are context-only replacement checks",
            "expected_values": {
                "worldpop_population_sum": round(worldpop["population_sum"]["population"], 3),
                "osm": osm_summary,
                "sentinel1_pre_count": sentinel.get("counts", {}).get("pre_count"),
                "sentinel1_post_count": sentinel.get("counts", {}).get("post_count"),
                "direct_window_replacement": False,
            },
            "decision": "map_and_image_layers_are_context_not_replacement",
        },
    ]
    answer_rows = [
        {
            "row_id": "landfall_peak_day_concentration",
            "calculation": "148.6/170.2 and 15.7/170.2",
            "value": "170.2 mm total; 0.873 peak-day fraction; 0.092 peak-hour fraction",
            "decision": "pass: landfall-day concentration is strong, but one-hour replacement fails",
        },
        {
            "row_id": "wind_pressure_timing_window",
            "calculation": "inclusive span from 2007-06-06T08:00 to 2007-06-06T12:00; 109.1/53.0",
            "value": "5 h span; 109.1 km/h gust; 53.0 km/h wind; 991.8 hPa pressure; ratio 2.058",
            "decision": "pass: gust, wind, and pressure extrema form a tight same-day timing window",
        },
        {
            "row_id": "independent_daily_same_day_support",
            "calculation": "NASA peak precipitation date equals NASA peak wind date equals Open-Meteo peak rain date; 170.2/69.54",
            "value": "same_day_support=true; NASA total 69.54 mm; NASA peak rain 50.68 mm; NASA peak wind 13.07 m/s; ratio 2.448",
            "decision": "pass: independent daily series supports the same timing with lower magnitude",
        },
        {
            "row_id": "regional_precip_max_context",
            "calculation": "Open-Meteo event total divided by ERA5, GPM, and CHIRPS regional maxima",
            "value": "point-to-regional ratios: ERA5 0.977, GPM 0.658, CHIRPS 0.991",
            "decision": "context: regional maxima inform magnitude but do not replace point-window timing",
        },
        {
            "row_id": "map_layer_nonreplacement_check",
            "calculation": "WorldPop/OSM derived context plus Sentinel pre/post availability",
            "value": f"WorldPop {round(worldpop['population_sum']['population'], 3)}; OSM elements {osm_summary['element_count']}; Sentinel pre/post {sentinel.get('counts', {}).get('pre_count')}/{sentinel.get('counts', {}).get('post_count')}; direct replacement=false",
            "decision": "context: map, exposure, and image layers do not replace the Oman point-window proof",
        },
    ]
    final_consistency = (
        "Use the co-timed landfall-day rain, gust, wind, and pressure window for the Oman phase; "
        "regional precipitation and map/image layers are secondary context."
    )

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": TARGET_FAMILY,
        "event": {
            "package_id": PACKAGE_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": "2007-06-01 to 2007-06-07",
        },
        "primary_gt": {
            "answer": ANSWER,
            "rows": answer_rows,
            "final_consistency": final_consistency,
        },
        "key_values": {
            "open_meteo_point": {
                "hour_count": len(times),
                "precipitation_total_mm": precip_total,
                "peak_daily_precipitation": {"date": peak_day_date, "value": peak_day_value},
                "peak_day_fraction_of_event_total": peak_day_fraction,
                "max_hourly_precipitation": peak_hour,
                "peak_hour_fraction_of_event_total": peak_hour_fraction,
                "max_wind_gust_10m": max_gust,
                "max_wind_speed_10m": max_wind,
                "min_pressure_msl": min_pressure,
                "co_timing_span_hours_inclusive": cotiming_span_hours_inclusive,
                "gust_to_wind_ratio": gust_to_wind_ratio,
            },
            "nasa_power_point": rows[2]["expected_values"],
            "regional_precipitation_summaries": regional_maxima,
            "map_layer_checks": rows[4]["expected_values"],
        },
        "required_rows": rows,
        "numeric_tolerances": {
            "precipitation_mm": 0.1,
            "fractions_and_ratios": 0.01,
            "wind_kmh": 0.1,
            "pressure_hpa": 0.1,
            "time_values": "exact hour or same date as stated",
            "boolean_values": "exact",
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "answer_schema_and_rows",
                    "points": 4,
                    "description": "Returns a compact JSON ledger with the final label and all five required row labels.",
                    "partial_credit": "Award 2-3 points if the output is readable but misses one row or has minor field-name drift; award 1 point if it is prose-only but contains most row results.",
                },
                {
                    "name": "rainfall_concentration",
                    "points": 4,
                    "description": "Computes 170.2 mm total, 148.6 mm peak day on 2007-06-06, 0.873 peak-day fraction, 15.7 mm peak hour, and 0.092 peak-hour fraction.",
                    "partial_credit": "Award 2-3 points for the correct total and peak-day fraction but missing peak-hour fraction or date; award 1 point for only identifying the rain peak day.",
                },
                {
                    "name": "wind_pressure_window",
                    "points": 4,
                    "description": "Computes the 5 h inclusive co-timing span, 109.1 km/h gust at 08:00, 53.0 km/h wind at 12:00, 991.8 hPa pressure at 12:00, and gust/wind ratio near 2.058.",
                    "partial_credit": "Award 2-3 points for the correct extrema but wrong span convention or missing ratio; award 1 point for same-day timing only.",
                },
                {
                    "name": "nasa_daily_support",
                    "points": 3,
                    "description": "Uses NASA POWER 69.54 mm total, 50.68 mm daily precipitation peak and 13.07 m/s wind peak on 20070606, plus the 2.448 Open-Meteo/NASA total ratio.",
                    "partial_credit": "Award 1-2 points for the same-day conclusion with incomplete daily totals or ratio.",
                },
                {
                    "name": "regional_ratio_context",
                    "points": 2,
                    "description": "Computes ERA5, GPM, and CHIRPS regional maxima and point-to-regional ratios near 0.977, 0.658, and 0.991.",
                    "partial_credit": "Award 1 point for computing two ratios or for the correct qualitative comparison without all values.",
                },
                {
                    "name": "map_layer_nonreplacement",
                    "points": 2,
                    "description": "Applies the map/image nonreplacement check: WorldPop/OSM are derived context, Sentinel pre/post counts are 0/0, and population or amenity summaries are not used as a local loss denominator.",
                    "partial_credit": "Award 1 point for stating the nonreplacement result without the exposure or Sentinel details.",
                },
                {
                    "name": "concise_output_no_overclaim",
                    "points": 1,
                    "description": "Keeps the final consistency sentence concise and avoids Category 5 Oman landfall, surge-height, local loss-denominator, or mapped-inundation overclaims.",
                    "partial_credit": "Award no more than 0.5 points if the answer is correct but adds one unverified impact claim.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "Values are extracted from local CSX-126 package files; no network access is used. WorldPop, OSM, and Sentinel products are used as package-declared derived context; coordinates, place names, bounding boxes, and georeferencing metadata inside masked products are not used for event-location validity scoring.",
        },
    }

    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    output_path.write_text(json.dumps(output, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
